import React from 'react';
// Assuming Tailwind CSS is set up in your project

function AboutUsPage() {
  return (
    // Main container for the page content
    // Uses Tailwind for padding, background, text color, and responsiveness
    // Styles are designed to work within a parent controlling dark mode
    <div className="container mx-auto px-4 py-8 max-w-3xl bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-200 rounded-lg shadow-md my-8">

      {/* Main Heading */}
      <h1 className="text-3xl md:text-4xl font-bold text-center text-blue-600 dark:text-blue-400 mb-8">
        About Us
      </h1>

      {/* About Content */}
      <div className="text-lg space-y-6 text-gray-700 dark:text-gray-300">
        <p>
          Welcome to [Your Site Name]! We created this tool with a simple goal in mind: to provide a fast, free, and easy way for anyone to download videos from Facebook for personal, offline use.
        </p>
        <p>
          We understand that sometimes you want to save a memorable video shared by a friend, a helpful tutorial, or an interesting clip to watch later without an internet connection. Facebook doesn't offer a built-in download option for most videos, which is where we come in.
        </p>
        <p>
          Our mission is to make the process as straightforward as possible. Just paste the video URL, and we'll help you get the download link quickly and efficiently, offering different quality options when available.
        </p>
        <p>
          We are committed to providing a reliable service while respecting user privacy and copyright. We do not store the videos you download on our servers, and we encourage users to only download videos they have permission to save.
        </p>
        {/* Optional: Add a section about the team or vision */}
        {/*
        <div>
          <h2 className="text-2xl font-semibold text-gray-800 dark:text-gray-100 mb-3">Our Vision</h2>
          <p>
            We aim to be your go-to solution for downloading videos from various platforms, continuously improving our service and adding support for more sources while maintaining our core values of simplicity, speed, and privacy.
          </p>
        </div>
        */}
      </div>

      {/* Optional: Link back to home or contact */}
      {/*
      <p className="text-center mt-8 text-gray-600 dark:text-gray-400 text-sm">
        Have questions? <a href="/contact" className="text-blue-600 dark:text-blue-400 hover:underline">Contact Us</a>.
      </p>
      */}

    </div>
  );
}

export default AboutUsPage;
